import { describe, expect, it } from "vitest";
import { shout } from "./volume.js";

describe("shout", () => {
  it("uppercases lowercase text", () => {
    expect(shout("hello")).toBe("HELLO");
  });

  it("leaves already-uppercase text unchanged", () => {
    expect(shout("HELLO")).toBe("HELLO");
  });

  it("handles mixed content", () => {
    expect(shout("a1!b2")).toBe("A1!B2");
  });
});

